insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$leme$q$, $q$https://www.leme.sp.gov.br/leis/decretos_do_executivo/2019/7163.pdf (Decreto 7.163/2019) ; https://www.leme.sp.gov.br/leis/decretos_do_executivo/2014/6424.pdf (Decreto 6.424/2014) ; https://www.leme.sp.gov.br/leis/decretos_do_executivo/2019/7327.pdf (Decreto 7.327/2019) ; https://sapl.leme.sp.leg.br/media/sapl/public/normajuridica/2006/5957/codigolei_02-000464.pdf (LC 464/2006)$q$, $q$Atos oficiais de Leme: domínio público (Lei 9.610/1998 art. 8º IV). Geometria: OpenStreetMap (ODbL 1.0, © colaboradores do OSM).$q$, 29, $q$Dec. 7.163/2019 (e Dec. 6.424/2014, art. 6º, red. Dec. 7.327/2019): caminhão com PBT acima de 5 t proibido de transitar e de fazer carga e descarga nas vias centrais (Área Azul), seg–sex 9h–18h e sáb 9h–13h. A LC 464/2006 (área e horários alterados por decreto) e a Estrada Municipal Ricardo Landgraf (hgv=no só no OSM) ficam registradas como desativadas. Decretos de 2021–2025 não estão publicados on-line.$q$);
